diff --git a/src/components/embedUtils.ts b/src/components/embedUtils.ts
new file mode 100644
index 0000000..f7e8d9c
--- /dev/null
+++ b/src/components/embedUtils.ts
@@ -0,0 +1,85 @@
+import { sanitizeHtml } from "@excalidraw/common";
+
+export interface ParsedEmbedContent {
+  title: string;
+  styles: string[];
+  scripts: string[];
+  bodyContent: string;
+  metaTags: Record<string, string>;
+}
+
+/**
+ * Safely parse embed HTML content without executing any scripts or
+ * allowing HTML injection. Extracts only safe, known elements.
+ */
+export function parseEmbedContent(html: string, sourceUrl: string): ParsedEmbedContent {
+  // Create a sandboxed parser that doesn't execute scripts
+  const parser = new DOMParser();
+  const doc = parser.parseFromString(html, "text/html");
+  
+  // Extract title safely
+  const title = doc.querySelector("title")?.textContent?.trim() || "Excalidraw Embed";
+  
+  // Extract styles - only allow link rel=stylesheet and style tags with safe content
+  const styles: string[] = [];
+  doc.querySelectorAll('link[rel="stylesheet"]').forEach((link) => {
+    const href = link.getAttribute("href");
+    if (href && isSafeUrl(href, sourceUrl)) {
+      styles.push(`<link rel="stylesheet" href="${escapeAttribute(href)}">`);
+    }
+  });
+  
+  doc.querySelectorAll("style").forEach((style) => {
+    // Sanitize CSS content - only allow safe CSS
+    const cssContent = sanitizeCss(style.textContent || "");
+    if (cssContent) {
+      styles.push(`<style>${cssContent}</style>`);
+    }
+  });
+  
+  // Extract scripts - only allow known safe script sources
+  const scripts: string[] = [];
+  doc.querySelectorAll("script[src]").forEach((script) => {
+    const src = script.getAttribute("src");
+    if (src && isSafeScriptSource(src, sourceUrl)) {
+      scripts.push(`<script src="${escapeAttribute(src)}"></script>`);
+    }
+  });
+  
+  // Inline scripts are never allowed for security
+  
+  // Extract body content - sanitize heavily
+  const body = doc.querySelector("body");
+  let bodyContent = "";
+  if (body) {
+    // Clone and sanitize the body content
+    const clonedBody = body.cloneNode(true) as HTMLElement;
+    // Remove all event handlers and dangerous attributes
+    removeDangerousAttributes(clonedBody);
+    // Remove script tags entirely
+    clonedBody.querySelectorAll("script").forEach((s) => s.remove());
+    // Remove iframe, object, embed tags
+    clonedBody.querySelectorAll("iframe, object, embed").forEach((el) => el.remove());
+    bodyContent = sanitizeHtml(clonedBody.innerHTML);
+  }
+  
+  // Extract meta tags (only safe ones)
+  const metaTags: Record<string, string> = {};
+  doc.querySelectorAll("meta").forEach((meta) => {
+    const name = meta.getAttribute("name") || meta.getAttribute("property");
+    const content = meta.getAttribute("content");
+    if (name && content && isSafeMetaName(name)) {
+      metaTags[name] = escapeAttribute(content);
+    }
+  });
+  
+  return { title, styles, scripts, bodyContent, metaTags };
+}
+
+/**
+ * Build a safe srcdoc from parsed embed content.
+ * Constructs HTML manually instead of trusting raw input.
+ */
+export function buildSafeSrcdoc(parsed: ParsedEmbedContent): string {
+  const metaTagsHtml = Object.entries(parsed.metaTags)
+    .map(([name, content]) => `<meta name="${escapeAttribute(name)}" content="${content}">`)
+    .join("\n");
+  
+  return `<!DOCTYPE html>
+<html>
+<head>
+  <meta charset="utf-8">
+  <title>${escapeHtml(parsed.title)}</title>
+  ${metaTagsHtml}
+  ${parsed.styles.join("\n")}
+  ${parsed.scripts.join("\n")}
+  <style>
+    /* Default safe styles for embeds */
+    body { margin: 0; padding: 0; font-family: system-ui, sans-serif; }
+    * { box-sizing: border-box; }
+  </style>
+</head>
+<body>
+  ${parsed.bodyContent}
+</body>
+</html>`;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#039;");
+}
+
+function escapeAttribute(text: string): string {
+  return text
+    .replace(/&/g, "&amp;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#039;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;");
+}
+
+function isSafeUrl(url: string, baseUrl: string): boolean {
+  try {
+    const parsed = new URL(url, baseUrl);
+    const base = new URL(baseUrl);
+    // Only allow same-origin or known safe CDN domains
+    return parsed.origin === base.origin || 
+           parsed.hostname.endsWith(".excalidraw.com") ||
+           parsed.hostname === "cdn.jsdelivr.net" ||
+           parsed.hostname === "unpkg.com";
+  } catch {
+    return false;
+  }
+}
+
+function isSafeScriptSource(src: string, baseUrl: string): boolean {
+  try {
+    const parsed = new URL(src, baseUrl);
+    const base = new URL(baseUrl);
+    // Only allow scripts from same origin or trusted CDNs
+    return parsed.origin === base.origin ||
+           parsed.hostname === "cdn.jsdelivr.net" ||
+           parsed.hostname === "unpkg.com" ||
+           parsed.hostname.endsWith(".excalidraw.com");
+  } catch {
+    return false;
+  }
+}
+
+function isSafeMetaName(name: string): boolean {
+  const safeNames = [
+    "description", "viewport", "theme-color", "color-scheme",
+    "og:title", "og:description", "og:image", "og:type",
+    "twitter:card", "twitter:title", "twitter:description", "twitter:image"
+  ];
+  return safeNames.includes(name.toLowerCase());
+}
+
+function sanitizeCss(css: string): string {
+  // Basic CSS sanitization - remove dangerous constructs
+  return css
+    .replace(/expression\s*\(/gi, "") // Remove CSS expressions
+    .replace(/javascript\s*:/gi, "") // Remove javascript: URLs
+    .replace(/@import/gi, "") // Remove @import
+    .replace(/behavior\s*:/gi, ""); // Remove IE behaviors
+}
+
+function removeDangerousAttributes(element: HTMLElement): void {
+  const dangerousAttrs = [
+    "onclick", "onload", "onerror", "onmouseover", "onmouseout",
+    "onkeydown", "onkeyup", "onfocus", "onblur", "onchange",
+    "onsubmit", "onreset", "onselect", "onresize", "onscroll",
+    "oncontextmenu", "ondblclick", "onmousedown", "onmouseup",
+    "onmousemove", "onmouseenter", "onmouseleave", "onwheel",
+    "ontouchstart", "ontouchend", "ontouchmove", "ontouchcancel",
+    "onpointerdown", "onpointerup", "onpointermove", "onpointerenter",
+    "onpointerleave", "onpointercancel", "ongotpointercapture",
+    "onlostpointercapture", "onanimationstart", "onanimationend",
+    "onanimationiteration", "ontransitionend", "onbeforeunload",
+    "onunload", "onhashchange", "onpagehide", "onpageshow",
+    "onpopstate", "onmessage", "onmessageerror"
+  ];
+  
+  // Remove from this element
+  dangerousAttrs.forEach((attr) => element.removeAttribute(attr));
+  
+  // Remove from all descendants
+  element.querySelectorAll("*").forEach((el) => {
+    dangerousAttrs.forEach((attr) => el.removeAttribute(attr));
+    // Also remove javascript: URLs from href, src, etc.
+    ["href", "src", "action", "formaction", "background"].forEach((attr) => {
+      const value = el.getAttribute(attr);
+      if (value && value.trim().toLowerCase().startsWith("javascript:")) {
+        el.removeAttribute(attr);
+      }
+    });
+  });
+}
