@@ -0,0 +1,45 @@
+import { CompiledInstruction, Message, PublicKey } from '@solana/web3.js';
+import { SYSTEM_PROGRAM_ID } from './constants';
+
+export interface TransferSolInstruction {
+  source: PublicKey;
+  recipient: PublicKey;
+  amount: number;
+}
+
+/**
+ * Finds the transfer SOL instruction associated with a specific reference key.
+ * The reference key is used as a memo or in the instruction accounts to identify
+ * the specific Solana Pay payment.
+ */
+export function getTransferSolInstruction(
+  message: Message,
+  referenceKey: PublicKey
+): TransferSolInstruction | null {
+  const accountKeys = message.accountKeys;
+
+  for (const instruction of message.compiledInstructions) {
+    const programId = accountKeys[instruction.programIdIndex];
+
+    // Check if this is a system program transfer instruction
+    if (!programId.equals(SYSTEM_PROGRAM_ID)) {
+      continue;
+    }
+
+    // System program transfer instruction has data starting with 0x02 (transfer)
+    if (instruction.data[0] !== 2) {
+      continue;
+    }
+
+    // Check if the reference key is in the instruction accounts
+    // (typically as a memo account or in the accounts list)
+    const instructionAccounts = instruction.accountKeyIndexes.map(
+      (i) => accountKeys[i]
+    );
+
+    if (!instructionAccounts.some((key) => key.equals(referenceKey))) {
+      continue;
+    }
+
+    // Parse the transfer instruction
+    // Accounts: [source, destination]
+    const source = accountKeys[instruction.accountKeyIndexes[0]];
+    const recipient = accountKeys[instruction.accountKeyIndexes[1]];
+
+    // Amount is in lamports, encoded as little-endian u64 at offset 1
+    const amount = Number(
+      instruction.data.slice(1, 9).reduce((acc, byte, i) => acc + byte * 256 ** i, 0)
+    );
+
+    return { source, recipient, amount };
+  }
+
+  return null;
+}
