+/**
+ * Strict HTTP request parser to prevent request smuggling vulnerabilities.
+ * Enforces RFC 7230 compliance for header parsing.
+ */
+
+export interface ParsedRequest {
+  method: string
+  path: string
+  version: string
+  headers: Headers
+  body: ReadableStream | null
+}
+
+export class HttpParser {
+  private buffer: Buffer = Buffer.alloc(0)
+  private headersComplete = false
+  private contentLength: number | null = null
+  private isChunked = false
+  
+  /**
+   * Parse incoming data and return complete requests
+   * Throws on ambiguous or malformed requests
+   */
+  parse(data: Buffer): ParsedRequest[] {
+    this.buffer = Buffer.concat([this.buffer, data])
+    const requests: ParsedRequest[] = []
+    
+    while (!this.headersComplete && this.buffer.length > 0) {
+      const headerEnd = this.buffer.indexOf('\r\n\r\n')
+      if (headerEnd === -1) {
+        // Need more data for headers
+        if (this.buffer.length > 8192) {
+          throw new Error('Headers too large')
+        }
+        break
+      }
+      
+      const headerData = this.buffer.subarray(0, headerEnd)
+      this.buffer = this.buffer.subarray(headerEnd + 4)
+      this.parseHeaders(headerData)
+      this.headersComplete = true
+    }
+    
+    if (this.headersComplete) {
+      // Body parsing would happen here with strict content-length/chunked handling
+      // For this fix, we focus on header validation
+      this.headersComplete = false
+    }
+    
+    return requests
+  }
+  
+  private parseHeaders(data: Buffer): void {
+    const lines = data.toString().split('\r\n')
+    const requestLine = lines[0].split(' ')
+    
+    if (requestLine.length !== 3) {
+      throw new Error('Invalid request line')
+    }
+    
+    const headers = new Headers()
+    let hasContentLength = false
+    let hasTransferEncoding = false
+    let contentLengthValue: string | null = null
+    
+    for (let i = 1; i < lines.length; i++) {
+      const line = lines[i]
+      if (!line) continue
+      
+      const colonIndex = line.indexOf(':')
+      if (colonIndex === -1) {
+        throw new Error('Invalid header format')
+      }
+      
+      const name = line.substring(0, colonIndex).toLowerCase().trim()
+      const value = line.substring(colonIndex + 1).trim()
+      
+      // Check for header injection
+      if (name.includes('\0') || value.includes('\0')) {
+        throw new Error('Null byte in header')
+      }
+      
+      if (name === 'content-length') {
+        if (hasContentLength && contentLengthValue !== value) {
+          throw new Error('Multiple Content-Length headers with different values')
+        }
+        hasContentLength = true
+        contentLengthValue = value
+        const parsed = parseInt(value, 10)
+        if (isNaN(parsed) || parsed < 0) {
+          throw new Error('Invalid Content-Length value')
+        }
+        this.contentLength = parsed
+      } else if (name === 'transfer-encoding') {
+        hasTransferEncoding = true
+        const encodings = value.toLowerCase().split(',').map(e => e.trim())
