+	allowSubprocess: boolean;
+}
+
+export interface PythonSandboxResult {
+	output: unknown;
+	error?: string;
+	timedOut: boolean;
+}
+
+const DEFAULT_OPTIONS: PythonSandboxOptions = {
+	timeout: 30000,
+	memoryLimit: 128 * 1024 * 1024,
+	allowedModules: ['json', 'math', 'datetime', 're', 'itertools', 'collections', 'statistics'],
+	blockedModules: [
+		'os', 'sys', 'subprocess', 'shutil', 'pathlib', 'importlib', 'pkgutil', 'runpy', 'site',
