+	blockedBuiltins: [
+		'__import__', 'eval', 'exec', 'compile', 'open', 'input', 'breakpoint', 'help',
+		'license', 'credits', 'copyright', 'quit', 'exit', 'getattr', 'setattr', 'delattr',
