+		'reversed', 'zip', 'map', 'filter', 'sorted', 'any', 'all', 'sum', 'min', 'max', 'pow',
+		'abs', 'round', 'divmod', 'bin', 'hex', 'oct', 'chr', 'ord', 'ascii', 'repr', 'format'
+	],
+	allowNetwork: false,
+	allowFileSystem: false,
+	allowSubprocess: false,
+};
+
+const SANDBOX_WRAPPER = `
+import sys
+import builtins
+import importlib
+import json
+
+# Block dangerous builtins
+{blocked_builtins_code}
+
+# Block dangerous modules
+{blocked_modules_code}
+
+# Restrict imports to allowed modules only
+original_import = builtins.__import__
+
+def restricted_import(name, globals=None, locals=None, fromlist=(), level=0):
+    if name in {allowed_modules_set}:
+        return original_import(name, globals, locals, fromlist, level)
+    if name.startswith('_') or any(name.startswith(b + '.') for b in {blocked_modules_set}):
+        raise ImportError(f"Import of '{name}' is not allowed")
+    # Check if parent module is blocked
+    for blocked in {blocked_modules_set}:
+        if name == blocked or name.startswith(blocked + '.'):
+            raise ImportError(f"Import of '{name}' is not allowed")
+    return original_import(name, globals, locals, fromlist, level)
+
+builtins.__import__ = restricted_import
+
+# Execute user code
+try:
+    {user_code}
+    # Capture result from last expression if any
+    if '_result' in locals():
+        print('__RESULT__', json.dumps(_result, default=str))
+except Exception as e:
+    print('__ERROR__', json.dumps({'type': type(e).__name__, 'message': str(e)}))
+    sys.exit(1)
+`;
+
+function generateBlockedBuiltinsCode(blockedBuiltins: string[]): string {
+	return blockedBuiltins
+		.map((name) => `try: del builtins.${name}\nexcept AttributeError: pass`)
+		.join('\n');
+}
+
+function generateBlockedModulesCode(blockedModules: string[]): string {
+	const modules = JSON.stringify(blockedModules);
+	return `
+blocked_modules = ${modules}
